CREATE TABLE setor (id INTEGER PRIMARY KEY, nome TEXT NOT NULL);
CREATE TABLE func (id INTEGER PRIMARY KEY, nome TEXT NOT NULL, setor_id INTEGER REFERENCES setor(id));
INSERT INTO setor VALUES (10,'Vendas'),(20,'TI'),(30,'RH');
INSERT INTO func VALUES (1,'Ana',10),(2,'Bruno',NULL),(3,'Clara',20),(4,'Davi',10);

SELECT s.nome AS setor, f.nome AS funcionario
FROM setor s
LEFT JOIN func f ON f.setor_id = s.id
ORDER BY setor, funcionario;
